<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="Petitions">
      <NuxtLink v-if="isManager" :to="{ name: 'verification-ballots-configuration' }">
        <Button>Import Petition</Button>
      </NuxtLink>
    </PageTitle>
    <BallotsListFilters :params="params" />
    <Card>
      <AppLoader v-if="isLoading" subject="petitions" variant="inline" />
      <AppError v-else-if="error" :error="error" title="Failed to load petitions" variant="table" />
      <ResponsiveTable v-else rounded>
        <ResponsiveTableHeader>
          <ResponsiveTableHead class="text-nowrap"> Submitted At </ResponsiveTableHead>
          <ResponsiveTableHead class="text-nowrap"> Submitted By </ResponsiveTableHead>
          <ResponsiveTableHead> Canvasser </ResponsiveTableHead>
          <ResponsiveTableHead> Project </ResponsiveTableHead>
          <ResponsiveTableHead> Pages </ResponsiveTableHead>
          <ResponsiveTableHead> Signatures </ResponsiveTableHead>
          <ResponsiveTableHead> Status </ResponsiveTableHead>
        </ResponsiveTableHeader>
        <ResponsiveTableBody>
          <ResponsiveTableEmpty
            v-if="!data || data.items.length === 0"
            :colspan="7"
            :cols="4"
            :cols-sm="4"
            class="text-center"
          >
            <AppGuidedEmpty v-if="showGuided && guidedContent" v-bind="guidedContent" variant="table" />
            <AppEmpty v-else variant="table" subject="petitions" />
          </ResponsiveTableEmpty>
          <ResponsiveTableRow
            v-for="ballot in data?.items"
            :key="ballot.id"
            :to="{ name: 'verification-ballots-id', params: { id: ballot.id.toString() } }"
          >
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Submitted At">
              {{ formatDateTzToFormat(ballot.submitted_at, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Submitted By">
              {{ username(ballot.submitted_by) }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Canvasser">
              {{ username(ballot.canvasser) }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Project">
              {{ ballot.project.name }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="1" label="Pages"> {{ ballot.page_count }} </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="1" label="Signatures">
              <SignatureStatistics
                :valid-signatures="ballot.valid_signature_count"
                :submitted-signatures="ballot.submitted_signature_count"
              />
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="2" label="Status">
              <Badge :variant="getVerificationBallotsStatusBadge(ballot.status).variant">{{
                getVerificationBallotsStatusBadge(ballot.status).label
              }}</Badge>
            </ResponsiveTableCell>
          </ResponsiveTableRow>
        </ResponsiveTableBody>
        <ResponsiveTableFooter
          v-if="!error && !isLoading && data && data.total_count > 0"
          :colspan="7"
          :cols="4"
          :cols-sm="4"
        >
          <AppPagination :page="params.page" :total="data.total_count" :size="params.size" label="petitions" />
        </ResponsiveTableFooter>
      </ResponsiveTable>
    </Card>
  </section>
</template>

<script setup lang="ts">
import { getVerificationBallotsStatusBadge } from '~/constants/verifications/ballotsStatus';
import { type BallotStatus, getBallotVerificationList, type GetBallotVerificationListData } from '~/client';
import { ballotsGuidedEmpty } from '~/constants/guidedEmpty/ballots';

useHead({
  title: 'Petitions',
});

definePageMeta({
  roles: ['admin', 'manager'],
  backLabel: 'petitions',
});

const { isManager, timezone } = useUserRole();

const params = computed((): NonNullable<GetBallotVerificationListData['query']> => {
  const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
    useRoute('verification-ballots').query.subcontractor_company_ids
  );

  const queryParams = {
    ...parsePagination(useRoute('verification-ballots').query),
    canvasser_ids: processArrayQueryParameterFromUrl<string>(useRoute('verification-ballots').query.canvasser_ids),
    subcontractor_company_ids,
    include_unassigned,
    manager_ids: processArrayQueryParameterFromUrl<string>(useRoute('verification-ballots').query.manager_ids),
    project_ids: processArrayQueryParameterFromUrl<string>(useRoute('verification-ballots').query.project_ids),
    statuses: processArrayQueryParameterFromUrl<BallotStatus>(useRoute('verification-ballots').query.statuses),
    sort_by: useRoute('verification-ballots').query.sort_by || 'created_at',
    sort_type:
      useRoute('verification-ballots').query.sort_type && isSortType(useRoute('verification-ballots').query.sort_type)
        ? useRoute('verification-ballots').query.sort_type
        : 'desc',
    from_date: useRoute('verification-ballots').query.from_date?.toString() || undefined,
    search_query: useRoute('verification-ballots').query.search_query?.toString() || undefined,
  };

  return Object.fromEntries(Object.entries(queryParams).filter(([_, value]) => value !== undefined)) as NonNullable<
    GetBallotVerificationListData['query']
  >;
});

const { data, error, isLoading } = useQuery({
  key: () => ['ballots.list', params.value],
  query: () => getBallotVerificationList({ composable: '$fetch', query: ref(params.value) }),
  staleTime: 0,
});

const isEmpty = computed(() => !data.value || data.value.items.length === 0);
const { guidedContent, showGuided } = useGuidedEmpty(ballotsGuidedEmpty, isEmpty);
</script>
